#!/bin/bash
# Plan 30 D: real time with everything on (lanes, markings, guidance, signs with YOLO full frame, HUD), three runs each
# of town05_30hz, s3a and s7 (VIDEOS="..." for others).  usage: realtime_d.sh OUT_DIR [imgsz] [max_inference_fps]
# NICE=n: the sign detector at that niceness; SIGNS=0: without the sign detector (the lane-only reference);
# SIGNS_EXTRA="name:=value ...": more detector parameters (e.g. raw_cdr:=true).
# (Do not edit this file while it runs: bash reads it as it goes.)
cd /home/jaehun/Desktop/vision-road;source /opt/ros/humble/setup.bash;source install/setup.bash
OUT=$1;IMGSZ=${2:-1920};FPS=${3:-0.0};mkdir -p $OUT
if [ "${SIGNS:-1}" = 1 ];then SA=(--signs --signs-nice ${NICE:-0} --signs-arg full_frame:=true imgsz:=$IMGSZ max_inference_fps:=$FPS ${SIGNS_EXTRA:-});else SA=();fi
for v in ${VIDEOS:-town05 town05_s3a_zigzag_cross town05_s7_lights};do
  for i in 1 2 3;do
    # As run_lane_hud.sh runs it (and the plan 26 measurement): display filter inside road_node, lane guidance on,
    # the stand-in vehicle state (the replay sends images and the pose only).
    python3 tools/realtime_eval.py --video $v --output $OUT/${v}_$i "${SA[@]}" \
      --launch-arg display_filter_inline:=true lane_guidance:=true fake_vehicle_state:=true > $OUT/${v}_$i.log 2>&1;echo "$v $i $?"
  done
done
